function same_advanced($a,$b,$message){global $ghr_advanced_count;++$ghr_advanced_count;if($a!==$b){throw new RuntimeException($message.': '.var_export($a,true).' != '.var_export($b,true));}echo "PASS $message\n";}
function denied_advanced($fn,$message){global $ghr_advanced_count;try{$fn();}catch(DomainException|InvalidArgumentException $e){++$ghr_advanced_count;echo "PASS $message\n";return;}throw new RuntimeException('Expected rejection: '.$message);}
