$insert_token=static function($user,$token,$target,$expiry)use($wpdb){return DB::insert('identity_verifications',array('user_id'=>$user,'purpose'=>'phone','target'=>$target,'token_hash'=>hash_hmac('sha256',$user.':'.$token,wp_salt()),'expires_at'=>$expiry));};
$insert_token($u,$token,$phone,gmdate('Y-m-d H:i:s',time()+600));Membership::confirm($u,'phone',$token);same_advanced(Membership::get($u)['verified_phone'],$phone,'Phone verified with secure token');denied_advanced(fn()=>Membership::confirm($u,'phone',$token),'Verification token single use');
$insert_token($v,'654321',$phone,gmdate('Y-m-d H:i:s',time()+600));$wpdb->suppress_errors(true);denied_advanced(fn()=>Membership::confirm($v,'phone','654321'),'Duplicate verified phone denied');$wpdb->suppress_errors(false);
