Wallet::post($v,'referral',1000,$run.'earn','earn',$run,0,'Fixture');$spend=Wallet::reserve($v,'referral',1000,$run.'-spend-intent',hash('sha256','cart'));Wallet::bind($spend['id'],$v,999991);Wallet::commit($spend['id'],$v,999991);Wallet::post($v,'referral',-1000,$run.'reverse','reversal',$run,0,'Refund already-spent reward');same_advanced(Wallet::account($v,'referral')['posted'],-1000,'Spent earning reversal records reward debt');Wallet::post($v,'referral',1500,$run.'recovery','earn',$run,0,'Future earnings recover debt');same_advanced(Wallet::account($v,'referral')['available'],500,'Future earnings offset debt');
// Holds/manual approval for referral commissions.
$p=new WC_Product_Simple();$p->set_name('Advanced test');$p->set_regular_price('1000');$p->set_tax_status('none');$p->save();Settings::save(array('referral_approval'=>true,'hold_days'=>0,'bonus_products'=>array(),'excluded_products'=>array(),'excluded_categories'=>array()));
$o=wc_create_order(array('customer_id'=>$u));$o->add_product($p,1);$o->update_meta_data('_ghr_referrer',$v);$o->calculate_totals();$o->update_status('completed');Orders::reconcile($o->get_id());$c=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DB::table('referral_conversions').' WHERE order_id=%d',$o->get_id()),ARRAY_A);same_advanced($c['status'],'review','Manual referral approval holds commission');$balance=Wallet::account($v,'referral')['posted'];Referral::approve((int)$c['id'],'Review complete');Orders::reconcile($o->get_id());same_advanced(Wallet::account($v,'referral')['posted'],$balance+2000,'Approved commission posted once');
// Suspension restricts redemption without destroying existing earnings.
$previous=Wallet::account($u,'seeds')['posted'];Membership::status($u,'suspended','Test restriction');Orders::reconcile($o->get_id());same_advanced(Wallet::account($u,'seeds')['posted'],$previous,'Suspension retains existing earnings');denied_advanced(fn()=>Wallet::reserve($u,'seeds',1,$run.'-suspended',hash('sha256','cart')),'Suspension blocks redemption');Membership::status($u,'active','Resolved');
// Amount-only refunds require explicit allocations.
