add_filter('pre_wp_mail','__return_false');for($i=0;$i<5;$i++){DB::update(DB::table('notification_deliveries'),array('next_attempt'=>gmdate('Y-m-d H:i:s',time()-1)),array('id'=>$delivery));Notifications::deliver($delivery);}remove_filter('pre_wp_mail','__return_false');same_advanced(DB::row('notification_deliveries',$delivery)['state'],'failed','Notification retries stop at configured limit');same_advanced((int)DB::row('notification_deliveries',$delivery)['attempts'],5,'Exactly five provider attempts');
