wp_set_current_user($u);$server=rest_get_server();$request=new WP_REST_Request('POST','/ghr/v1/admin/commands/adjust');$request->set_header('X-WP-Nonce',wp_create_nonce('wp_rest'));$request->set_header('Content-Type','application/json');$request->set_body(wp_json_encode(array('user_id'=>$u,'wallet'=>'trust','amount'=>1000,'reference'=>$run,'reason'=>'forged')));same_advanced($server->dispatch($request)->get_status(),403,'Customer cannot forge administrator adjustment');
wp_set_current_user(0);$request=new WP_REST_Request('GET','/ghr/v1/me/wallets');same_advanced($server->dispatch($request)->get_status(),401,'Public visitor cannot access financial REST');
same_advanced((int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('wallet_accounts').' a WHERE posted<>(SELECT COALESCE(SUM(amount),0) FROM '.DB::table('wallet_transactions').' t WHERE t.account_id=a.id)'),0,'Ledger projections remain consistent after expiry, debt and refunds');
echo "ADVANCED PASS: $ghr_advanced_count assertions\n";
}finally{update_option('ghr_settings',$before,false);}
